export interface RatioPlaceholder {
  ratio: number;
  src: string;
}

/**
 * Placeholder photos grouped by standard aspect ratio -- several per ratio (not just one),
 * so a run of same-ratio slides (e.g. in a Carousel) can show real variety instead of one
 * image repeated. `resolveRatioPlaceholder` picks the closest matching ratio, then selects
 * among that ratio's own variants by index. 480px on the longer side so these hold up in
 * a reasonably large component, not just a thumbnail.
 * ~1441KB total, embedded as data URIs.
 */
